#nullable enable // autogenerated

using System.Collections.Generic;

namespace MVZ2.Resources
{
    public class ResourceDatabase<TKey, TResource> : IResourceProvider<TKey, TResource>
    {
        public void Register(TKey key, TResource sprite)
        {
            resources[key] = sprite;
            reversedDict[sprite] = key;
        }
        public void Unregister(TKey key)
        {
            if (resources.TryGetValue(key, out var resource))
            {
                resources.Remove(key);
                reversedDict.Remove(resource);
            }
        }

        public void Clear()
        {
            resources.Clear();
            reversedDict.Clear();
        }
        public TKey? GetKey(TResource sprite)
        {
            if (sprite == null)
                return default;
            if (reversedDict.TryGetValue(sprite, out var sprRef))
            {
                return sprRef;
            }
            return default;
        }
        public bool TryGet(TKey key, out TResource? sprite)
        {
            return resources.TryGetValue(key, out sprite);
        }
        public int Priority { get; set; }
        private readonly Dictionary<TKey, TResource> resources = new();
        private readonly Dictionary<TResource, TKey> reversedDict = new Dictionary<TResource, TKey>();
    }
}
